[{"name":"submit","line":15,"source":"async function submit(): Promise<void> {
  if (busy.value) return
  busy.value = true
  error.value = ''
  try {
    await login(username.value, password.value)
    password.value = ''
    await router.push('/')
  } catch (cause) {
    error.value = errorMessage(cause)
    password.value = ''
  } finally {
    busy.value = false
  }
}"}]

[{"name":"load","line":15,"source":"async function load(): Promise<void> {
  loading.value = true
  error.value = ''
  try {
    status.value = await identityApi.onboarding()
  } catch (cause) {
    error.value = errorMessage(cause)
  } finally {
    loading.value = false
    if (status.value && route.hash === '#operations') {
      await nextTick()
      document.getElementById('operations')?.scrollIntoView({ block: 'start' })
    }
  }
}"}]

