  }
}"}]

[{"name":"start","line":107,"source":"async function start(): Promise<void> {
  if (busy.value || dirty.value || rulesPending.value) return
  pageBusy.value = true
  error.value = ''
  info.value = ''
  selected.value = null
  try {
    run.value = await operationsApi.run(shopId.value, { ...scope }, crypto.randomUUID())
    offset.value = 0
    await readLists()
    info.value = '检查已保存。候选需经批准成为待办；已有处理状态已保留。'
  } catch (cause) {
    error.value = errorMessage(cause)
  } finally {
    pageBusy.value = false
  }
}"}]

