[{"name":"load","line":12,"source":"async function load(): Promise<void> {
  const token = ++sequence
  rule.value = null
  error.value = ''
  emit('pending', true)
  if (!props.shop) return
  try {
    const value = await rulesApi.current(props.shop, props.scope.channel, props.scope.data_identity)
    if (sequence !== token) return
    rule.value = value
    emit('loaded', value)
    emit('pending', false)
  } catch (cause) {
    if (sequence === token) error.value = errorMessage(cause)
  }
}"}]

[{"name":"recent","line":30,"source":"function recent(days: number): void {
  const now = Date.now()
  emit('update:start', new Date(now - days * 86400000).toISOString())
  emit('update:end', new Date(now).toISOString())
}"}]

[{"name":"select","line":50,"source":"function select(value: string): void {
  display.value = value
  localIssue = false
  try {
    const instant = resolveLocalTime(value, props.timezone)
    error.value = ''
    emit('update:modelValue', instant)
  } catch (cause) {
    // Keep invalid local input visible and prevent form submission. Never reuse
    // the last valid instant after a failed edit.
    localIssue = true
    emit('update:modelValue', 'invalid-local-time')
    error.value = cause instanceof Error ? cause.message : '请核对时间与时区。'
  }
}"}]

[{"name":"inputExact","line":65,"source":"function inputExact(value: string): void {
  localIssue = false
  error.value = exactTimeError(value, props.timezone)
  emit('update:modelValue', value)
}"}]

