[{"name":"inspect","line":26,"source":"async function inspect(): Promise<void> {
  const current = ++epoch
  const row = props.source.row_id
  const shop = props.shopId
  error.value = ''
  busy.value = true
  detail.value = null
  try {
    const result = await analyticsApi.source(shop, row)
    if (current === epoch) detail.value = result
  } catch (cause) {
    if (current === epoch) error.value = errorMessage(cause)
  } finally {
    if (current === epoch) busy.value = false
  }
}"}]

[{"name":"act","line":44,"source":"async function act(action: TaskAction): Promise<void> {
  if (busy.value || followUpDirty.value) return
  const target = props.task
  actionBusy.value = true
  emit('working', true)
  error.value = ''
  try {
    const result = await operationsApi.change(
      target.shop_id,
      target.id,
      target.version,
      action,
      note.value,
      due.value || null,
    )
    if (
      props.task.shop_id === target.shop_id &&
      props.task.id === target.id &&
      props.task.version === target.version
    )
      emit('updated', result)
  } catch (cause) {
    error.value = errorMessage(cause)
  } finally {
    actionBusy.value = false
    emit('working', false)
  }
}"}]

