[{"name":"act","line":51,"source":"async function act(action: 'record_evidence' | 'wait_source' | 'recheck'): Promise<void> {
  if (
    busy.value ||
    props.disabled ||
    !editable.value ||
    (action !== 'record_evidence' && dirty.value)
  )
    return
  const current = ++generation
  const target = props.task
  const evidence =
    action === 'record_evidence'
      ? {
          description: description.value,
          evidence_ref: evidenceRef.value,
          occurred_at: occurredAt.value,
          confirmed: confirmed.value,
        }
      : undefined
  busy.value = true
  emit('working', true)
  error.value = ''
  try {
    const result = await operationsApi.change(
      target.shop_id,
      target.id,
      target.version,
      action,
      target.note,
      target.due_at,
      evidence,
    )
    if (active && current === generation) emit('updated', result)
  } catch (cause) {
    if (active && current === generation) error.value = errorMessage(cause)
  } finally {
    if (active && current === generation) {
      busy.value = false
      emit('working', false)
    }
  }
}"}]

