[{"name":"refresh","line":145,"source":"async function refresh(): Promise<void> {
  if (!shopId.value || dirty.value || busy.value) return
  await perform(async () => {
    await load()
    if (selected.value) selected.value = await supportApi.get(shopId.value, selected.value.id)
    const mid = workspace.value?.message.id
    workspace.value = null
    resetEvidence()
    if (mid && messages.value.some((m) => m.id === mid))
      workspace.value = await supportApi.workspace(shopId.value, mid)
  })
}"}]

[{"name":"preview","line":39,"source":"async function preview(): Promise<void> {
  busy.value = true
  error.value = ''
  batch.value = null
  allowUpdates.value = false
  try {
    fields.value = (await importsApi.catalog()).messages
    const keys = ['message_id', 'sent_at', 'body', 'language', 'order_id'] as const
    const escape = (value: string) => `"${value.replaceAll('"', '""')}"`
    const csv = `${keys.join(',')}\n${keys.map((key) => escape(form[key])).join(',')}\n`
    const file = new File([csv], 'manual-message.csv', { type: 'text/csv' })
    const uploaded = await importsApi.upload(props.shopId, file, {
      filename: file.name,
      kind: 'messages',
      source_channel: form.channel,
      data_identity: form.identity,
      timezone: props.timezone,
    })
    batch.value = await importsApi.preview(uploaded.id, uploaded.version, uploaded.mapping, {})
    fingerprint.value = current.value
  } catch (cause) {
    error.value = errorMessage(cause)
  } finally {
    busy.value = false
  }
}"}]

[{"name":"save","line":65,"source":"async function save(): Promise<void> {
  if (!batch.value || dirty.value) return
  busy.value = true
  error.value = ''
  try {
    await importsApi.commit(batch.value.id, batch.value.version, allowUpdates.value)
    batch.value = null
    form.body = ''
    form.message_id = ''
    form.order_id = ''
    emit('saved')
  } catch (cause) {
    error.value = errorMessage(cause)
  } finally {
    busy.value = false
  }
}"}]

[{"name":"select","line":50,"source":"function select(value: string): void {
  display.value = value
