[{"name":"load","line":53,"source":"async function load(more = false): Promise<void> {
  const seq = ++sequence
  const shop = props.shop
  if (!more) {
    grants.value = []
    next.value = null
  }
  if (!shop) return
  loading.value = true
  error.value = ''
  try {
    const page = await authorizationsApi.list(shop, more ? (next.value ?? undefined) : undefined)
    const focused = !more && props.focusId ? await authorizationsApi.get(shop, props.focusId) : null
    if (seq !== sequence || props.shop !== shop) return
    grants.value = more ? [...grants.value, ...page.items] : page.items
    if (focused) grants.value = [focused, ...grants.value.filter((g) => g.id !== focused.id)]
    next.value = page.next_before_id
    if (focused) await revealRecord(`authorization-${focused.id}`)
  } catch (cause) {
    if (seq === sequence) error.value = errorMessage(cause)
  } finally {
    if (seq === sequence) loading.value = false
  }
}"}]

[{"name":"create","line":77,"source":"async function create(): Promise<void> {
  if (!props.run || !canCreate.value || !confirmed.value || loading.value || props.busy) return
  const shop = props.shop
  loading.value = true
  error.value = ''
  info.value = ''
  try {
    await authorizationsApi.create(props.run, count.value, hours.value, createRequest)
    if (shop === props.shop) {
      info.value = '授权已保存。可用于当前候选，或按相同范围启动新的检查。'
      confirmed.value = false
      createRequest = crypto.randomUUID()
      await load()
    }
  } catch (cause) {
    if (shop === props.shop) error.value = errorMessage(cause)
  } finally {
    loading.value = false
  }
}"}]

[{"name":"change","line":97,"source":"async function change(grant: InternalAuthorization, useId?: number): Promise<void> {
  if (loading.value || props.busy) return
  loading.value = true
  error.value = ''
  info.value = ''
  try {
    if (useId !== undefined) {
      if (!restoreConfirm.value[useId]) return
      await authorizationsApi.revert(grant, useId)
    } else await authorizationsApi.revoke(grant)
    if (grant.shop_id === props.shop) {
      info.value =
        useId !== undefined
          ? '本次新增候选已拒绝，历史保留，额度不返还。'
          : '授权已撤销，已保存结果保留。'
      await load()
    }
  } catch (cause) {
    if (grant.shop_id === props.shop) error.value = errorMessage(cause)
  } finally {
    loading.value = false
  }
}"}]

