[{"name":"save","line":161,"source":"async function save(content?: ExpenseContent): Promise<void> {
  if (content)
    pending.value = {
      shop: shopId.value,
      id: editing.value?.id,
      body: {
        ...scope,
        request_id: crypto.randomUUID(),
        confirm: true,
        version: editing.value?.version ?? 0,
        content,
      },
    }
  const request = pending.value
  if (!request || busy.value) return
  await action(async (valid) => {
    hideContent()
    const response = await expensesApi.write(request.shop, request.body, request.id)
    if (!valid()) return
    pending.value = null
    accept(response)
    await list(valid)
  })
}"}]

[{"name":"control","line":185,"source":"async function control(retry = false): Promise<void> {
  if (!retry) {
    if (!saved.value || !confirmed.value) return
    pendingControl.value = {
      shop: shopId.value,
      id: saved.value.id,
      action: controlAction.value,
      body: { version: saved.value.version, confirm: true, request_id: crypto.randomUUID() },
    }
  }
  const request = pendingControl.value
  if (!request) return
  await action(async (valid) => {
    hideContent()
    const response = await expensesApi.control(
      request.shop,
      request.id,
      request.action,
      request.body,
    )
    if (!valid()) return
    pendingControl.value = null
    accept(response)
    await list(valid)
  })
}"}]

