[{"name":"control","line":225,"source":"async function control(retry = false): Promise<void> {
  if (!retry) {
    if (!saved.value || !controlConfirmed.value) return
    pendingControl.value = {
      id: saved.value.id,
      action: controlAction.value,
      body: { request_id: crypto.randomUUID(), version: saved.value.version, confirm: true },
    }
  }
  const request = pendingControl.value
  if (!request || busy.value || props.disabled) return
  invalidate()
  emit('invalidated')
  await action(async (valid) => {
    let response: SettlementSaved
    try {
      response = await api.control(props.shopId, request.id, request.action, request.body)
    } catch (cause) {
      if (valid() && cause instanceof ApiError && cause.status >= 400 && cause.status < 500)
        pendingControl.value = null
      throw cause
    }
    if (valid()) {
      saved.value = response
      shownVersion.value = response.content_version
      pendingControl.value = null
      if (response.status === 'cleared') {
        Object.assign(content, { statement_id: '', note: '', receipts: [] })
        pending.value = null
      }
      controlAction.value = response.status === 'withdrawn' ? 'clear' : 'withdraw'
    }
  })
}"}]

[{"name":"recent","line":30,"source":"function recent(days: number): void {
  const now = Date.now()
  emit('update:start', new Date(now - days * 86400000).toISOString())
  emit('update:end', new Date(now).toISOString())
}"}]

[{"name":"select","line":50,"source":"function select(value: string): void {
  display.value = value
  localIssue = false
  try {
    const instant = resolveLocalTime(value, props.timezone)
    error.value = ''
    emit('update:modelValue', instant)
  } catch (cause) {
    // Keep invalid local input visible and prevent form submission. Never reuse
    // the last valid instant after a failed edit.
    localIssue = true
    emit('update:modelValue', 'invalid-local-time')
    error.value = cause instanceof Error ? cause.message : '请核对时间与时区。'
  }
}"}]

[{"name":"inputExact","line":65,"source":"function inputExact(value: string): void {
  localIssue = false
  error.value = exactTimeError(value, props.timezone)
  emit('update:modelValue', value)
}"}]

