[{"name":"connectAction","line":64,"source":"async function connectAction(action: 'connect' | 'verify' | 'disconnect'): Promise<void> {
  if (!channel.value || busy.value || (action === 'connect' && !confirmed.value)) return
  busy.value = true
  error.value = ''
  try {
    channel.value =
      action === 'connect'
        ? await outboundApi.connect(shop.value)
        : action === 'verify'
          ? await outboundApi.verify(shop.value, channel.value.id!, code.value)
          : await outboundApi.disconnect(shop.value, channel.value.id!)
    selected.value = null
    confirmed.value = false
    code.value = ''
  } catch (cause) {
    error.value = errorMessage(cause)
  } finally {
    busy.value = false
  }
}"}]

[{"name":"connectAction","line":64,"source":"async function connectAction(action: 'connect' | 'verify' | 'disconnect'): Promise<void> {
  if (!channel.value || busy.value || (action === 'connect' && !confirmed.value)) return
  busy.value = true
  error.value = ''
  try {
    channel.value =
      action === 'connect'
        ? await outboundApi.connect(shop.value)
        : action === 'verify'
          ? await outboundApi.verify(shop.value, channel.value.id!, code.value)
          : await outboundApi.disconnect(shop.value, channel.value.id!)
    selected.value = null
    confirmed.value = false
    code.value = ''
  } catch (cause) {
    error.value = errorMessage(cause)
  } finally {
    busy.value = false
  }
}"}]

