[{"name":"decide","line":226,"source":"async function decide(kind: EditAction): Promise<void> {
  const edit = saved.value
  if (!edit) return
  await action(async (valid) => {
    saved.value = null
    clearEditor()
    pending.value = null
    const result = await productEditsApi.decide(edit, kind)
    if (!valid()) return
    accept(result)
    await loadHistory(valid)
  })
}"}]

